def f(x):
    return x**3-5*x+1
def bisection_method(a,b,E):
    if f(a)*f(b)>0:
        print("Root doesn't exist in this interval")
        return None
    c=(a+b)/2.0
    print("a\t\tb\t\tc")
    while abs(b-a)/2.0>E:
        c=(a+b)/2.0
        print(f"{a:.5f}\t{b:.5f}\t{c:.5f}")
        if f(c)==0:
            break
        elif f(a)*f(c)<0:
            b=c
        else:
            a=c
    return c
a=float(input("Enter a: "))
